package agent;

import agent.Review.Bug;
import agent.Review.Severity;
import java.util.List;

// A pipeline: Reviewer -> gate (plain Java) -> Writer
public class ReviewPipeline {

    // The gate: plain Java, no LLM. Keep only the serious bugs.
    static List<Bug> seriousBugs(Review review) {
        return review.bugs().stream()
                .filter(bug -> bug.severity() != Severity.LOW)
                .toList();
    }

    public static void main(String[] args) {
        String file = args.length > 0 ? args[0] : "UserService.java";

        Agent reviewer = new Agent("Reviewer",
                "You are a senior Java reviewer. Read the file "
                + "with your tool. Report real bugs only.",
                List.of(FileTools.READ_FILE), FileTools::run);

        Agent writer = new Agent("Writer",
                "You turn bug lists into a short, friendly report "
                + "for a junior developer. Max 8 lines.",
                List.of(), call -> "Error: no tools");

        // Step 1: a typed review
        Review review = reviewer.run("Review " + file, Review.class);
        System.out.println("Summary: " + review.summary());

        // Step 2: the gate decides if the pipeline continues
        List<Bug> serious = seriousBugs(review);
        if (serious.isEmpty()) {
            System.out.println("No serious bugs: Writer skipped.");
            return;
        }

        // Step 3: the Writer gets only the serious bugs
        String report = writer.run("Write the report:\n" + serious);
        System.out.println("\n=== REPORT ===\n" + report);
    }
}

package agent;

import com.anthropic.client.AnthropicClient;
import com.anthropic.client.okhttp.AnthropicOkHttpClient;
import com.anthropic.models.messages.ContentBlockParam;
import com.anthropic.models.messages.MessageCreateParams;
import com.anthropic.models.messages.StopReason;
import com.anthropic.models.messages.StructuredContentBlock;
import com.anthropic.models.messages.StructuredMessage;
import com.anthropic.models.messages.StructuredMessageCreateParams;
import com.anthropic.models.messages.Tool;
import com.anthropic.models.messages.ToolResultBlockParam;
import com.anthropic.models.messages.ToolUseBlock;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;

// One agent = its own system prompt, its own tools, its own context
public class Agent {

    // Reads your key from the ANTHROPIC_API_KEY variable
    private static final AnthropicClient CLIENT =
            AnthropicOkHttpClient.fromEnv();

    private final String name;
    private final String model;
    private final String systemPrompt;
    private final List<Tool> tools;
    private final Function<ToolUseBlock, String> toolRunner;

    public Agent(String name, String systemPrompt, List<Tool> tools,
                 Function<ToolUseBlock, String> toolRunner) {
        this(name, "claude-opus-5-5", systemPrompt, tools,
                toolRunner);
    }

    // NEW: choose the model per agent (a small one for simple jobs)
    public Agent(String name, String model, String systemPrompt,
                 List<Tool> tools,
                 Function<ToolUseBlock, String> toolRunner) {
        this.name = name;
        this.model = model;
        this.systemPrompt = systemPrompt;
        this.tools = tools;
        this.toolRunner = toolRunner;
    }

    // A plain-text answer, for agents that write for humans
    record Answer(String text) {}

    public String run(String task) {
        return run(task, Answer.class).text();
    }

    // The agent loop, with a typed answer (a Java record)
    public <T> T run(String task, Class<T> type) {
        System.out.println("[" + name + "] working...");

        // The answer must match the record: the SDK builds the schema
        StructuredMessageCreateParams.Builder<T> chat =
            MessageCreateParams.builder()
                .model(model)
                .maxTokens(16000L)
                .system(systemPrompt)
                .addUserMessage(task)
                .outputConfig(type);
        tools.forEach(chat::addTool);

        for (int turn = 0; turn < 10; turn++) {
            StructuredMessage<T> reply =
                    CLIENT.messages().create(chat.build());
            chat.addMessage(reply.rawMessage());

            // No tool requested? Return the typed answer.
            StopReason why = reply.stopReason().orElse(null);
            if (why != StopReason.TOOL_USE) {
                return reply.content().stream()
                        .flatMap(block -> block.text().stream())
                        .findFirst().orElseThrow()
                        .text();
            }

            // Run every tool it asked for, send all results back
            List<ContentBlockParam> results = new ArrayList<>();
            for (StructuredContentBlock<T> block : reply.content()) {
                block.toolUse().ifPresent(call -> {
                    System.out.println("  [" + name + "] tool: "
                            + call.name());
                    results.add(ContentBlockParam.ofToolResult(
                            ToolResultBlockParam.builder()
                                    .toolUseId(call.id())
                                    .content(toolRunner.apply(call))
                                    .build()));
                });
            }
            chat.addUserMessageOfContentBlockParams(results);
        }
        throw new IllegalStateException(name + ": too many turns");
    }
}

package agent;

// The router's answer: which specialist, and why
public record Route(Specialist specialist, String reason) {

    public enum Specialist { SECURITY, CONCURRENCY, TESTS, GENERAL }
}

package agent;

import agent.Route.Specialist;
import java.util.List;

// Routing: a small, fast model picks the right specialist
public class ReviewRouter {

// The switch must cover every specialist: the compiler checks it
static String focusFor(Specialist specialist) {
    return switch (specialist) {
        case SECURITY -> "security";
        case CONCURRENCY -> "concurrency";
        case TESTS -> "testing";
        case GENERAL -> "code quality";
    };
}

// A specialist = the same Agent class with a focused prompt
static Agent specialist(String focus) {
    return new Agent(focus + " reviewer",
            "You are a Java " + focus + " expert. Read the "
            + "file with your tool. Report real " + focus
            + " bugs only.",
            List.of(FileTools.READ_FILE), FileTools::run);
}

    public static void main(String[] args) {
        String file = args.length > 0 ? args[0] : "UserService.java";

        // Step 1: route. One cheap call, the code is in the task.
        Route route = ROUTER.run("File " + file + ":\n"
                + FileTools.readFile(file), Route.class);
        System.out.println("Route: " + route.specialist()
                + " (" + route.reason() + ")");

        // Step 2: the chosen specialist does the real review
        Agent reviewer = specialist(focusFor(route.specialist()));
        Review review = reviewer.run("Review " + file, Review.class);

        review.bugs().forEach(bug -> System.out.println("  line "
                + bug.line() + " [" + bug.severity() + "] "
                + bug.problem()));
    }
}

